(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-4-prof-shah-style-quiz-version-4"]={"title":"Prof. Shah Style Integration Set 4 — Anatomy Exam 4","category":"Anatomy","exam":"Exam 4","sem":"summer-1-2026","questions":[{"q":"Which muscle extends and medially rotates the arm at the shoulder but is NOT one of the four rotator cuff muscles?","choices":["Teres minor","Infraspinatus","Supraspinatus","Teres major"],"answer":3,"exp":"Teres major extends and medially rotates the arm, but it is not part of the rotator cuff (which is supraspinatus, infraspinatus, teres minor, and subscapularis). — Appendicular Musculature - Shahsv.pptx, Slide 14"},{"q":"Which rotator cuff muscle adducts AND laterally rotates the arm at the shoulder?","choices":["Teres major","Teres minor","Supraspinatus","Subscapularis"],"answer":1,"exp":"Teres minor is the rotator cuff muscle that adducts and laterally rotates the arm. — Appendicular Musculature - Shahsv.pptx, Slide 14"},{"q":"Which muscle flexes the elbow and occupies the LATERAL compartment of the forearm?","choices":["Brachialis","Biceps brachii","Brachioradialis","Anconeus"],"answer":2,"exp":"Brachioradialis flexes the elbow and is the main muscle of the lateral forearm compartment. — Appendicular Musculature - Shahsv.pptx, Slide 98"},{"q":"Which small posterior muscle assists extension at the elbow and works with the triceps brachii?","choices":["Supinator","Pronator teres","Brachialis","Anconeus"],"answer":3,"exp":"Anconeus is the small posterior muscle that assists the triceps brachii in extending the elbow. — Appendicular Musculature - Shahsv.pptx, Slide 23"},{"q":"Which gluteal-group muscle is a primary ABDUCTOR of the hip (important for keeping the pelvis level in gait)?","choices":["Gluteus maximus","Gluteus medius","Piriformis","Adductor longus"],"answer":1,"exp":"Gluteus medius (with gluteus minimus) abducts the hip and stabilizes the pelvis during walking. — Appendicular Musculature - Shahsv.pptx, Slide 55"},{"q":"Which muscle of the MEDIAL compartment of the thigh adducts and medially rotates the hip?","choices":["Gluteus minimus","Rectus femoris","Biceps femoris","Adductor longus"],"answer":3,"exp":"Adductor longus, in the medial (adductor) compartment of the thigh, adducts and medially rotates the hip. — Appendicular Musculature - Shahsv.pptx, Slide 60"},{"q":"Which hamstring muscle flexes the lower leg and lies on the MEDIAL side of the posterior thigh alongside the semitendinosus?","choices":["Biceps femoris","Rectus femoris","Semimembranosus","Vastus lateralis"],"answer":2,"exp":"Semimembranosus is a medial hamstring that flexes the lower leg (and extends the hip), running with the semitendinosus. — Appendicular Musculature - Shahsv.pptx, Slide 69"},{"q":"Which two-headed superficial posterior-leg muscle plantar flexes the foot and joins the calcaneal (Achilles) tendon?","choices":["Gastrocnemius","Tibialis posterior","Tibialis anterior","Fibularis longus"],"answer":0,"exp":"Gastrocnemius is the two-headed superficial calf muscle that plantar flexes the foot and inserts via the calcaneal tendon. — Appendicular Musculature - Shahsv.pptx, Slide 75"},{"q":"Which scalp muscle (the frontal belly of the occipitofrontalis) raises the eyebrows and wrinkles the forehead, innervated by CN VII?","choices":["Frontalis","Corrugator supercilii","Temporalis","Orbicularis oculi"],"answer":0,"exp":"The frontalis (frontal belly of occipitofrontalis) raises the eyebrows and wrinkles the forehead via the facial nerve (CN VII). — Axial Musculature - Shahsv.pptx, Slide 30"},{"q":"Which extra-ocular muscle rotates the eye UP and laterally and is innervated by cranial nerve III?","choices":["Inferior oblique","Superior oblique","Lateral rectus","Inferior rectus"],"answer":0,"exp":"The inferior oblique rotates the eye up and laterally and is supplied by CN III. — Axial Musculature - Shahsv.pptx, Slide 22"},{"q":"Which thin, broad neck muscle tenses the skin of the neck and depresses the mandible, innervated by the cervical branch of the facial nerve (CN VII)?","choices":["Platysma","Sternocleidomastoid","Sternohyoid","Omohyoid"],"answer":0,"exp":"The platysma is the thin broad muscle that tenses the neck and depresses the mandible, supplied by the cervical branch of CN VII. — Axial Musculature - Shahsv.pptx, Slide 34"},{"q":"Which tongue muscle retracts the tongue (drawing it in) and is innervated by the hypoglossal nerve (CN XII)?","choices":["Palatoglossus","Genioglossus","Styloglossus","Hyoglossus"],"answer":2,"exp":"Styloglossus retracts (draws in) the tongue and is supplied by CN XII. — Axial Musculature - Shahsv.pptx, Slide 40"},{"q":"Which deep intrinsic back muscle group is made of three muscles that together EXTEND THE NECK?","choices":["Interspinales","Semispinalis","Intertransversarii","Iliocostalis"],"answer":1,"exp":"The semispinalis is a set of three deep muscles that together extend the neck. — Axial Musculature - Shahsv.pptx, Slide 57"},{"q":"Which flat abdominal muscle compresses the abdomen, depresses the ribs, AND laterally flexes the trunk, forming the most SUPERFICIAL of the three flat layers?","choices":["Transversus abdominis","Rectus abdominis","External oblique","Diaphragm"],"answer":2,"exp":"The external oblique is the most superficial flat abdominal muscle; it compresses the abdomen, depresses the ribs, and laterally flexes the trunk. — Axial Musculature - Shahsv.pptx, Slide 69"},{"q":"Which intermediate extrinsic back muscle ELEVATES the ribs to assist ventilation?","choices":["Serratus posterior inferior","Trapezius","Serratus posterior superior","Erector spinae"],"answer":2,"exp":"Serratus posterior superior is an intermediate extrinsic muscle that elevates the ribs for ventilation. — Axial Musculature - Shahsv.pptx, Slide 51"},{"q":"Which scapular feature is the lateral continuation of the spine that forms the acromioclavicular joint with the clavicle?","choices":["Acromion","Coracoid process","Glenoid cavity","Suprascapular notch"],"answer":0,"exp":"The acromion is the lateral end of the scapular spine and articulates with the clavicle at the acromioclavicular joint. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 10"},{"q":"Which proximal ulnar process forms the 'point' of the elbow and fits into the olecranon fossa of the humerus?","choices":["Coronoid process","Olecranon","Radial notch","Styloid process"],"answer":1,"exp":"The olecranon is the proximal ulnar process forming the point of the elbow; it seats in the humeral olecranon fossa during extension. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 18"},{"q":"Which coxal-bone landmark is the 'sit bone' that bears weight when sitting and gives origin to the hamstrings?","choices":["Iliac crest","Ischial tuberosity","Pubic tubercle","Greater sciatic notch"],"answer":1,"exp":"The ischial tuberosity is the weight-bearing 'sit bone' and the origin of the hamstrings. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 37"},{"q":"Which cartilaginous midline joint unites the right and left pubic bones anteriorly?","choices":["Pubic symphysis","Sacroiliac joint","Acetabulum","Obturator foramen"],"answer":0,"exp":"The pubic symphysis is the cartilaginous joint uniting the two pubic bones in the anterior midline. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 35"},{"q":"Which tarsal bone sits on top of the calcaneus and articulates with the tibia and fibula to form the ankle joint?","choices":["Calcaneus","Talus","Navicular","Medial cuneiform"],"answer":1,"exp":"The talus articulates superiorly with the tibia and fibula (the ankle joint) and sits on the calcaneus. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 61"},{"q":"Which tarsal bone is the heel bone and the largest of the tarsals?","choices":["Talus","Calcaneus","Navicular","Cuboid"],"answer":1,"exp":"The calcaneus is the heel bone and the largest tarsal bone. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 61"},{"q":"Which bone has a ramus, an angle, a condylar process, a coronoid process, and the mental foramen?","choices":["Maxilla","Zygomatic bone","Temporal bone","Mandible"],"answer":3,"exp":"The mandible bears the ramus, angle, condylar and coronoid processes, and the mental foramen. — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 49"},{"q":"Which opening on the mandible transmits the mental nerve (a branch of the mandibular nerve, V3)?","choices":["Infra-orbital foramen","Supra-orbital foramen","Mental foramen","Optic canal"],"answer":2,"exp":"The mental foramen transmits the mental nerve, a branch of the mandibular nerve (V3). — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 46"},{"q":"Which facial bone forms the INFERIOR portion of the bony nasal septum?","choices":["Vomer","Perpendicular plate of the ethmoid","Palatine bone","Inferior nasal concha"],"answer":0,"exp":"The vomer forms the inferior portion of the bony nasal septum. — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 47"},{"q":"Which cranial suture lies in the midline between the two parietal bones?","choices":["Coronal suture","Lambdoid suture","Squamous suture","Sagittal suture"],"answer":3,"exp":"The sagittal suture runs in the midline between the two parietal bones. — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 24"},{"q":"Which structure of the vertebral column consists of FIVE fused vertebrae and bears the sacral promontory, ala, and auricular surface?","choices":["The sacrum","The coccyx","The atlas","A lumbar vertebra"],"answer":0,"exp":"The sacrum is five fused vertebrae and carries the sacral promontory, ala, and auricular surface (for the sacroiliac joint). — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 92"},{"q":"Which vertebrae are distinguished by having costal facets that articulate with the ribs?","choices":["Cervical vertebrae","Lumbar vertebrae","The sacrum","Thoracic vertebrae"],"answer":3,"exp":"Thoracic vertebrae have superior/inferior costal facets (and transverse costal facets) for rib articulation. — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 85"},{"q":"Which membranous area is the largest 'soft spot' of the infant skull, allowing skull distortion during birth?","choices":["Posterior fontanelle","Sphenoidal fontanelle","Anterior fontanelle","Mastoid fontanelle"],"answer":2,"exp":"The anterior fontanelle is the largest fontanelle — the baby's 'soft spot' — allowing the skull to mold during childbirth. — Anatomy of the Axial Skeleton - Shahsv.pptx, Slide 58"},{"q":"Which of the three parts of the coxal bone is the superior, fan-shaped portion whose crest is palpable at the waistline?","choices":["Ischium","Pubis","Sacrum","Ilium"],"answer":3,"exp":"The ilium is the large superior fan-shaped part of the coxal bone; its iliac crest is palpable at the waist. — Anatomy of the Appendicular Skeleton - Shahsv.pptx, Slide 33"},{"q":"Which infrahyoid strap muscle depresses the hyoid bone and elevates the larynx?","choices":["Sternocleidomastoid","Thyrohyoid","Masseter","Temporalis"],"answer":1,"exp":"Thyrohyoid depresses the hyoid and elevates the larynx. — Axial Musculature - Shahsv.pptx, Slide 43"}]};
